"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[23731],{43236:e=>{e.exports=JSON.parse('[{"title":"Accelerating Multi-Agent Orchestration with Speculative Dispatching","authors":["J. Ye","S. Islam","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop","type":"Poster","date":"July, 2026","month":7,"year":2026,"tags":["IOWarp"],"links":{"poster":"http://cs.iit.edu/~scs/assets/files/ye2026accelerating.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/ye2026accelerating.bib","citation":"http://cs.iit.edu/~scs/assets/files/ye2026accelerating.txt"},"slug":"ye-2026-accelerating-multi-agent-orchestration-with-speculative-539c","abstract":"Scientific computing workflows are increasingly being restructured around autonomous AI agents. These agents coordinate complex tasks across heterogeneous tools and infrastructure, ranging from molecular simulations spanning quantum chemistry solvers and machine learning potentials to cross-facility manufacturing experiments orchestrated by multi-agent teams. However, existing orchestration approaches either follow static execution graphs defined at design time or delegate routing to an LLM that greedily selects the next agent at each step, without considering resource availability, heterogeneous model and provider selection, and infrastructure constraints. Achieving resource-aware, dynamic, and deterministic orchestration that reasons about task decomposition, agent capabilities, and infrastructure state demands complex planning and dispatching decisions at runtime. This may introduce significant latency before any agent can begin execution. We propose a speculative dispatch mechanism to accelerate multi-agent orchestration. We are the first to apply speculative execution to the dispatch decision. Specifically, our approach speculatively dispatches agents ahead of time while the full orchestration decision is being computed. Since speculative dispatch can mispredict, a reconciliation engine reconciles the speculative and optimal dispatch plans. Unlike single-agent speculation approaches that accept or discard results entirely, our framework commits correct work, salvages partial matches, and flushes mispredictions, reducing the cost of misprediction. As workload patterns evolve over time, a learner progressively refines speculation accuracy from reconciliation outcomes, enabling the system to improve dispatch predictions. Preliminary results show speculative planner produces partially correct dispatch plans (0.50-0.78 similarity) at 4-10x lower latency than optimal planner, confirming the latency-quality gap speculative dispatch exploits."},{"authors":["S. Islam","J. Cernuda","X.-H. Sun","A. Kougkas"],"date":"May, 2026","links":{"poster":"http://cs.iit.edu/~scs/assets/files/islam2026agenticsearch_poster.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/islam2026agenticsearch.bib","citation":"http://cs.iit.edu/~scs/assets/files/islam2026agenticsearch.txt"},"month":5,"slug":"islam-2026-agentic-search-9f3c","tags":["AI","LLM","MCP","HPC"],"title":"Agentic Search Efficiency for Scientific Data Discovery","type":"Poster","venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026), May 11, 2026","year":2026},{"title":"Accelerating Multi-Agent Orchestration with Speculative Dispatching","authors":["J. Ye","S. Islam","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop","type":"Poster","date":"May, 2026","month":5,"year":2026,"tags":["Multi-Agents","Speculative Dispatching"],"links":{"pdf":"http://cs.iit.edu/~scs/assets/files/ye2026-gcasr-poster-pythia.pdf"},"slug":"ye-2026-gcasr-poster-pythia","abstract":"Scientific computing workflows are increasingly being restructured around autonomous AI agents. These agents coordinate complex tasks across heterogeneous tools and infrastructure, ranging from molecular simulations spanning quantum chemistry solvers and machine learning potentials to cross-facility manufacturing experiments orchestrated by multi-agent teams. However, existing orchestration approaches either follow static execution graphs defined at design time or delegate routing to an LLM that greedily selects the next agent at each step, without considering resource availability, heterogeneous model and provider selection, and infrastructure constraints. Achieving resource-aware, dynamic, and deterministic orchestration that reasons about task decomposition, agent capabilities, and infrastructure state demands complex planning and dispatching decisions at runtime. This may introduce significant latency before any agent can begin execution. We propose a speculative dispatch mechanism to accelerate multi-agent orchestration. We are the first to apply speculative execution to the dispatch decision. Specifically, our approach speculatively dispatches agents ahead of time while the full orchestration decision is being computed. Since speculative dispatch can mispredict, a reconciliation engine reconciles the speculative and optimal dispatch plans. Unlike single-agent speculation approaches that accept or discard results entirely, our framework commits correct work, salvages partial matches, and flushes mispredictions, reducing the cost of misprediction. As workload patterns evolve over time, a learner progressively refines speculation accuracy from reconciliation outcomes, enabling the system to improve dispatch predictions. Preliminary results show speculative planner produces partially correct dispatch plans (0.50-0.78 similarity) at 4-10x lower latency than optimal planner, confirming the latency-quality gap speculative dispatch exploits."},{"authors":["S. Islam","J. Cernuda","I. Muradli","A. Kougkas","X.-H. Sun"],"date":"September, 2025","links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/islam2025aidriven.bib","citation":"http://cs.iit.edu/~scs/assets/files/islam2025aidriven.txt","extended abstract":"http://cs.iit.edu/~scs/assets/files/islam2025aidriven.pdf","poster":"http://cs.iit.edu/~scs/assets/files/islam2025aidriven_poster.pdf"},"month":9,"slug":"islam-2025-towards-ai-driven-01ae","tags":["AI","LLM","MCP","HPC"],"title":"Towards an AI-driven scientific workflow","type":"Poster","venue":"21st IEEE International Conference on eScience (eScience \'25), September 15-18, 2025","year":2025}]')}}]);